import { useState } from 'react'

/**
 * Sign-in details for a deployed demo.
 *
 * Set SHOW to false for any real deployment. Publishing working credentials is
 * obviously wrong there; it is obviously right on a portfolio link, where the
 * alternative is a visitor who cannot get past the front door.
 *
 * No candidate credentials are listed, because there are none to list. An exam
 * code is generated by a person, spent once, and never reused — a fixed one
 * printed here would contradict the model the whole system is built on.
 */
const SHOW = true

const STAFF = [
  { id: 'EXO001', password: 'control123', who: 'Exam office', note: 'Sees every subject; creates staff accounts' },
  { id: 'CS204', password: 'teach123', who: 'Dr. Rao', note: 'Algorithms, Data Structures' },
  { id: 'CS311', password: 'teach123', who: 'Prof. Sharma', note: 'Databases, System Design' },
]

export default function DemoCredentials() {
  const [open, setOpen] = useState(false)
  if (!SHOW) return null

  return (
    <section className="panel stack" style={{ padding: '1.1rem 1.25rem', gap: open ? '1rem' : 0 }}>
      <button
        onClick={() => setOpen((v) => !v)}
        className="spread"
        style={{
          background: 'none', border: 'none', padding: 0, width: '100%',
          cursor: 'pointer', textAlign: 'left', color: 'var(--ink)',
        }}
        aria-expanded={open}
      >
        <span className="row" style={{ gap: '.6rem' }}>
          <span className="tag tag-primary">demo</span>
          <span style={{ fontWeight: 600, fontSize: '.95rem' }}>Sign-in details for trying this out</span>
        </span>
        <span className="mono muted small">{open ? '−' : '+'}</span>
      </button>

      {open && (
        <>
          <div className="stack" style={{ gap: '.5rem' }}>
            <span className="eyebrow">Staff portal</span>
            {STAFF.map((person) => (
              <div key={person.id} className="row" style={{ gap: '.7rem', flexWrap: 'wrap' }}>
                <span className="mono" style={{ fontWeight: 600, minWidth: 74 }}>{person.id}</span>
                <span className="mono muted small" style={{ minWidth: 92 }}>{person.password}</span>
                <span className="small">{person.who}</span>
                <span className="small muted">{person.note}</span>
              </div>
            ))}
          </div>

          <div className="stack" style={{ gap: '.4rem', borderTop: '1px solid var(--rule-soft)', paddingTop: '.9rem' }}>
            <span className="eyebrow">Sitting an exam</span>
            <p className="small muted" style={{ margin: 0, lineHeight: 1.65 }}>
              Candidates have no password, so there is nothing to publish here. An exam code is
              generated by staff, opens one paper and is spent once used — printing a fixed one
              would defeat that. To sit a paper: sign in above, open <strong>Candidates</strong>,
              select <span className="mono">21BCS1042</span> and press <strong>Generate codes</strong>.
              Then sign out and enter that enrolment number and code here.
            </p>
          </div>
        </>
      )}
    </section>
  )
}
